/**
 * Client-side MCP instrumentation: W3C / Cursor HTTP inject on Streamable
 * HTTP + SSE fetches, SEP-414 `_meta.traceparent` on JSON-RPC params, and
 * CLIENT spans for `tools/list` / `tools/call`.
 */
import { context, SpanKind, SpanStatusCode, trace } from "@opentelemetry/api";
import { activeTraceparent, instrumentedFetch } from "../../otel.js";
import { attrs } from "./attrs.js";
const TRACER = "agent_sdk";
export function instrumentedMcpFetch(base = fetch) {
    return instrumentedFetch(base);
}
/** SEP-414 / OTel MCP carrier for `params._meta`. */
export function mcpTraceMeta() {
    const traceparent = activeTraceparent();
    if (traceparent === undefined) {
        return undefined;
    }
    return { traceparent };
}
export function runMcpClientSpan(args, fn) {
    const span = trace.getTracer(TRACER).startSpan(args.method, {
        kind: SpanKind.CLIENT,
        attributes: attrs({
            "rpc.system": "mcp",
            "mcp.method.name": args.method,
            "mcp.tool.name": args.toolName,
            "agent_sdk.mcp.connection": args.connection,
        }),
    });
    return context.with(trace.setSpan(context.active(), span), async () => {
        try {
            return await fn();
        }
        catch (error) {
            span.setStatus({
                code: SpanStatusCode.ERROR,
                message: error instanceof Error ? error.message : String(error),
            });
            throw error;
        }
        finally {
            span.end();
        }
    });
}
